  1→// Package cursor implements the Agent interface for Cursor.
  2→package cursor
  3→
  4→import (
  5→	"context"
  6→	"errors"
  7→	"fmt"
  8→	"os"
  9→	"path/filepath"
 10→	"regexp"
 11→	"time"
 12→
 13→	"github.com/entireio/cli/cmd/entire/cli/agent"
 14→	"github.com/entireio/cli/cmd/entire/cli/paths"
 15→)
 16→
 17→//nolint:gochecknoinits // Agent self-registration is the intended pattern
 18→func init() {
 19→	agent.Register(agent.AgentNameCursor, NewCursorAgent)
 20→}
 21→
 22→// CursorAgent implements the Agent interface for Cursor.
 23→//
 24→//nolint:revive // CursorAgent is clearer than Agent in this context
 25→type CursorAgent struct{}
 26→
 27→// NewCursorAgent creates a new Cursor agent instance.
 28→func NewCursorAgent() agent.Agent {
 29→	return &CursorAgent{}
 30→}
 31→
 32→// Name returns the agent registry key.
 33→func (c *CursorAgent) Name() agent.AgentName {
 34→	return agent.AgentNameCursor
 35→}
 36→
 37→// Type returns the agent type identifier.
 38→func (c *CursorAgent) Type() agent.AgentType {
 39→	return agent.AgentTypeCursor
 40→}
 41→
 42→// Description returns a human-readable description.
 43→func (c *CursorAgent) Description() string {
 44→	return "Cursor - AI-powered code editor"
 45→}
 46→
 47→func (c *CursorAgent) IsPreview() bool { return true }
 48→
 49→// DetectPresence checks if Cursor is configured in the repository.
 50→func (c *CursorAgent) DetectPresence(ctx context.Context) (bool, error) {
 51→	worktreeRoot, err := paths.WorktreeRoot(ctx)
 52→	if err != nil {
 53→		worktreeRoot = "."
 54→	}
 55→
 56→	cursorDir := filepath.Join(worktreeRoot, ".cursor")
 57→	if _, err := os.Stat(cursorDir); err == nil {
 58→		return true, nil
 59→	}
 60→	return false, nil
 61→}
 62→
 63→// GetSessionID extracts the session ID from hook input.
 64→func (c *CursorAgent) GetSessionID(input *agent.HookInput) string {
 65→	return input.SessionID
 66→}
 67→
 68→// ResolveSessionFile returns the path to a Cursor session file.
 69→// Cursor IDE uses a nested layout: <dir>/<id>/<id>.jsonl
 70→// Cursor CLI uses a flat layout: <dir>/<id>.jsonl
 71→// We prefer the nested path if it exists, otherwise fall back to flat.
 72→func (c *CursorAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
 73→	nested := filepath.Join(sessionDir, agentSessionID, agentSessionID+".jsonl")
 74→	if _, err := os.Stat(nested); err == nil {
 75→		return nested
 76→	}
 77→	return filepath.Join(sessionDir, agentSessionID+".jsonl")
 78→}
 79→
 80→// ProtectedDirs returns directories that Cursor uses for config/state.
 81→func (c *CursorAgent) ProtectedDirs() []string { return []string{".cursor"} }
 82→
 83→// GetSessionDir returns the directory where Cursor stores session transcripts.
 84→func (c *CursorAgent) GetSessionDir(repoPath string) (string, error) {
 85→	if override := os.Getenv("ENTIRE_TEST_CURSOR_PROJECT_DIR"); override != "" {
 86→		return override, nil
 87→	}
 88→
 89→	homeDir, err := os.UserHomeDir()
 90→	if err != nil {
 91→		return "", fmt.Errorf("failed to get home directory: %w", err)
 92→	}
 93→
 94→	projectDir := sanitizePathForCursor(repoPath)
 95→	return filepath.Join(homeDir, ".cursor", "projects", projectDir, "agent-transcripts"), nil
 96→}
 97→
 98→// ReadSession reads a session from Cursor's storage (JSONL transcript file).
 99→// Note: ModifiedFiles is left empty because Cursor's transcript format does not
100→// contain tool_use blocks. File detection relies on git status instead.
101→func (c *CursorAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
102→	if input.SessionRef == "" {
103→		return nil, errors.New("session reference (transcript path) is required")
104→	}
105→
106→	data, err := os.ReadFile(input.SessionRef)
107→	if err != nil {
108→		return nil, fmt.Errorf("failed to read transcript: %w", err)
109→	}
110→
111→	return &agent.AgentSession{
112→		SessionID:  input.SessionID,
113→		AgentName:  c.Name(),
114→		SessionRef: input.SessionRef,
115→		StartTime:  time.Now(),
116→		NativeData: data,
117→	}, nil
118→}
119→
120→// WriteSession writes a session to Cursor's storage (JSONL transcript file).
121→func (c *CursorAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
122→	if session == nil {
123→		return errors.New("session is nil")
124→	}
125→
126→	if session.AgentName != "" && session.AgentName != c.Name() {
127→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
128→	}
129→
130→	if session.SessionRef == "" {
131→		return errors.New("session reference (transcript path) is required")
132→	}
133→
134→	if len(session.NativeData) == 0 {
135→		return errors.New("session has no native data to write")
136→	}
137→
138→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
139→		return fmt.Errorf("failed to write transcript: %w", err)
140→	}
141→
142→	return nil
143→}
144→
145→// FormatResumeCommand returns an instruction to resume a Cursor session.
146→// Cursor is a GUI IDE, so there's no CLI command to resume a session directly.
147→func (c *CursorAgent) FormatResumeCommand(_ string) string {
148→	return "Open this project in Cursor to continue the session."
149→}
150→
151→// sanitizePathForCursor converts a path to Cursor's project directory format.
152→var nonAlphanumericRegex = regexp.MustCompile(`[^a-zA-Z0-9]`)
153→
154→func sanitizePathForCursor(path string) string {
155→	return nonAlphanumericRegex.ReplaceAllString(path, "-")
156→}
157→
158→// ChunkTranscript splits a JSONL transcript at line boundaries.
159→func (c *CursorAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
160→	chunks, err := agent.ChunkJSONL(content, maxSize)
161→	if err != nil {
162→		return nil, fmt.Errorf("failed to chunk JSONL transcript: %w", err)
163→	}
164→	return chunks, nil
165→}
166→
167→// ReassembleTranscript concatenates JSONL chunks with newlines.
168→func (c *CursorAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
169→	return agent.ReassembleJSONL(chunks), nil
170→}
