261→func TestHandleLifecycleCompaction_ResetsTranscriptOffset(t *testing.T) {
262→	// Cannot use t.Parallel() because we use t.Chdir()
263→	tmpDir := t.TempDir()
264→	t.Chdir(tmpDir)
265→
266→	// Initialize git repo with a commit (not empty)
267→	setupGitRepoWithCommit(t, tmpDir)
268→	paths.ClearWorktreeRootCache()
269→
270→	// Create .entire directory structure
271→	if err := os.MkdirAll(paths.EntireDir, 0o755); err != nil {
272→		t.Fatalf("Failed to create .entire: %v", err)
273→	}
274→
275→	// Create a transcript file
276→	transcriptPath := filepath.Join(tmpDir, "transcript.jsonl")
277→	transcriptContent := `{"type":"user","message":{"role":"user","content":"test prompt"}}` + "\n"
278→	if err := os.WriteFile(transcriptPath, []byte(transcriptContent), 0o644); err != nil {
279→		t.Fatalf("Failed to create transcript: %v", err)
280→	}
281→
282→	sessionID := "compaction-test-session"
283→
284→	// Create session state with non-zero transcript offset
285→	sessionState := &strategy.SessionState{
286→		SessionID:                 sessionID,
287→		CheckpointTranscriptStart: 50, // Non-zero offset to be reset
288→	}
289→	if err := strategy.SaveSessionState(context.Background(), sessionState); err != nil {
290→		t.Fatalf("Failed to save session state: %v", err)
291→	}
292→
293→	ag := newMockAgent()
294→	event := &agent.Event{
295→		Type:       agent.Compaction,
296→		SessionID:  sessionID,
297→		SessionRef: transcriptPath,
298→	}
299→
300→	// handleLifecycleCompaction resets the transcript offset regardless of other operations.
301→	// It fires EventCompaction which stays in ACTIVE phase and resets CheckpointTranscriptStart.
302→	err := handleLifecycleCompaction(context.Background(), ag, event)
303→	if err != nil {
304→		t.Logf("handleLifecycleCompaction returned error (expected in minimal test): %v", err)
305→	}
306→
307→	// Verify CheckpointTranscriptStart was reset to 0
308→	loadedState, loadErr := strategy.LoadSessionState(context.Background(), sessionID)
309→	if loadErr != nil {
310→		t.Fatalf("Failed to load session state after compaction: %v", loadErr)
311→	}
312→	if loadedState == nil {
313→		t.Fatal("Session state is nil after compaction")
314→	}
315→	if loadedState.CheckpointTranscriptStart != 0 {
316→		t.Errorf("CheckpointTranscriptStart = %d, want 0 (should be reset on compaction)",
317→			loadedState.CheckpointTranscriptStart)
318→	}
319→}
