// handleLifecycleSessionEnd handles session end: marks the session as ended.
// If the session is still ACTIVE (TurnEnd never fired or failed), dispatches
// a deferred turn-end to save a checkpoint before ending the session.
func handleLifecycleSessionEnd(ctx context.Context, ag agent.Agent, event *agent.Event) error {
	logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
	logging.Info(logCtx, "session-end",
		slog.String("event", event.Type.String()),
		slog.String("session_id", event.SessionID),
	)

	if event.SessionID == "" {
		return nil // No session to update
	}

	// Check if session is still ACTIVE (TurnEnd never fired or failed).
	// If so, dispatch a synthetic TurnEnd to save a checkpoint.
	state, _ := strategy.LoadSessionState(ctx, event.SessionID)
	if state != nil && state.Phase == session.PhaseActive {
		logging.Info(logCtx, "deferred turn-end: session ending while still active")
		syntheticEvent := &agent.Event{
			Type:       agent.TurnEnd,
			SessionID:  event.SessionID,
			SessionRef: event.SessionRef,
			Timestamp:  event.Timestamp,
		}
		if err := handleLifecycleTurnEnd(ctx, ag, syntheticEvent); err != nil {
			logging.Warn(logCtx, "deferred turn-end failed", slog.String("err", err.Error()))
		}
	}

	// Note: We intentionally don't clean up cached transcripts here.
	// Post-session commits (carry-forward in ENDED phase) may still need
	// the transcript to extract file changes. Cleanup is handled by
	// `entire clean` or when the session state is fully removed.

	if err := markSessionEnded(ctx, event.SessionID); err != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to mark session ended: %v\n", err)
	}
	return nil
}

