118→// For mid-session commits (no Stop/SaveStep called yet), the shadow branch may not exist.
119→// In this case, data is extracted from the live transcript instead.
120→func (s *ManualCommitStrategy) CondenseSession(ctx context.Context, repo *git.Repository, checkpointID id.CheckpointID, state *SessionState, committedFiles map[string]struct{}, opts ...condenseOpts) (*CondenseResult, error) {
