func TestParseHookEvent_TurnStart_ResolvesTranscriptPath(t *testing.T) {
	t.Parallel()

	// Set up a temp dir with a transcript file so resolveTranscriptRef can find it
	tmpDir := t.TempDir()
	t.Setenv("ENTIRE_TEST_CURSOR_PROJECT_DIR", tmpDir)

	// Create a flat-layout transcript file
	transcriptFile := filepath.Join(tmpDir, "conv-no-path.jsonl")
	if err := os.WriteFile(transcriptFile, []byte(`{"role":"user"}`+"\n"), 0o644); err != nil {
		t.Fatalf("failed to create transcript file: %v", err)
	}

